/** Renders docs/ROLES.md from tokens/roles.json plus every variant's resolved colors. */
export function renderRolesDoc({ rolesDoc, variants }) {
  const ids = Object.keys(variants);
  const labels = ids.map((id) => variants[id].label);

  const lines = [
    '<!-- GENERATED by `npm run build` from tokens/roles.json and tokens/semantic.json. Do not edit. -->',
    '',
    '# Semantic roles',
    '',
    'This is the contract every port honors. A port maps each role to something in its target app;',
    'it never invents colors of its own. See [SPEC.md](SPEC.md) for the rules of use.',
    '',
  ];

  for (const group of rolesDoc.groups) {
    lines.push(
      `## ${group.title}`,
      '',
      `| Role | Meaning | ${labels.join(' | ')} |`,
      `| --- | --- | ${ids.map(() => '---').join(' | ')} |`,
    );
    for (const [role, description] of Object.entries(group.roles)) {
      const values = ids.map((id) => `\`${variants[id].roles[role]}\``).join(' | ');
      lines.push(`| \`${role}\` | ${description} | ${values} |`);
    }
    lines.push('');
  }

  return lines.join('\n');
}
